import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom CUDA kernel for element-wise addition ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

# ---------- Custom CUDA kernel for matrix multiplication (naive GEMM) ----------
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int K, int N) {
    // Each thread computes one element of the output matrix C
    int row = blockIdx.y * 16 + threadIdx.y;
    int col = blockIdx.x * 16 + threadIdx.x;
    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += A[row * K + k] * B[k * N + col];
        }
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto sizeA = A.numel();
    int M = A.size(0);
    int K = A.size(1);   // assuming A is (M,K)
    int N = B.size(1);   // assuming B is (K,N)

    float* out_ptr = new float[M * N];  // placeholder, will be replaced by torch::zeros_like later
    auto out = torch::zeros_like(A);

    const int BLOCK_SIZE = 16;
    int num_blocks_row = (M + BLOCK_SIZE - 1) / BLOCK_SIZE;
    int num_blocks_col = (N + BLOCK_SIZE - 1) / BLOCK_SIZE;

    matmul_kernel<<<num_blocks_row, num_blocks_col, 1>>>(A.data_ptr<float>(), B.data_ptr<float()>, out.data_ptr<float()>, M, K, N);

    return out;
}
"""

elementmatmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

elementmatmul_cuda_source = matmul_kernel_source

# Load the custom operators
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

matmul = load_inline(
    name="matmul",
    cpp_sources=elementmatmul_cpp_source,
    cuda_sources=elementmatmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add
        self.matmul_cuda = matmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self.matmul_cuda(A, B)
